import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
} from "typeorm"
import {
    CodingProblemEntity,
    CodingSolutionRevealEntity,
    CodingSubmissionEntity,
    CodingVerdict,
    InjectPrimaryPostgreSQLEntityManager,
} from "@modules/databases"
import {
    CodingProblemNotFoundException,
} from "@modules/exceptions"
import {
    WinstonLog,
    WinstonService,
} from "@modules/winston"
import {
    EnqueueJudgeCodingSubmissionJobService,
} from "../jobs"
import {
    DeviceService,
} from "../device"
import type {
    AcceptedSubmissionSummaryRow,
    AcceptedSubmissionSummaryResult,
    GetAcceptedSubmissionSummaryParams,
    ListMyCodingSubmissionsParams,
    ListMyCodingSubmissionsResult,
    RecordSolutionRevealParams,
    RecordSolutionRevealResult,
    SubmitCodingSolutionParams,
    SubmitCodingSolutionResult,
} from "./types"

/** Default page size for submission history. */
const DEFAULT_PAGE_SIZE = 20

@Injectable()
/**
 * Write-side + history business logic for coding submissions: persist a new
 * submission in `pending` state and enqueue the async judging job, and page a
 * user's submission history for a problem.
 */
export class CodingSubmissionService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly enqueueJudgeCodingSubmissionJobService: EnqueueJudgeCodingSubmissionJobService,
        private readonly deviceService: DeviceService,
        private readonly winstonService: WinstonService,
    ) {}

    /**
     * Create a pending submission for the problem and enqueue its judging job.
     *
     * @param params - userId, problem slug, language, source
     * @returns the created submission id + the judging job id to subscribe to
     * @throws CodingProblemNotFoundException when the slug is unknown/disabled
     */
    async submit({
        userId,
        slug,
        language,
        sourceCode,
        telemetry,
        ipAddress = null,
        userAgent = null,
        fingerprint = null,
    }: SubmitCodingSolutionParams): Promise<SubmitCodingSolutionResult> {
        // resolve the target problem (must exist and be enabled)
        const problem = await this.entityManager.findOne(CodingProblemEntity,
            {
                where: {
                    slug,
                    enabled: true,
                },
            })
        // unknown/disabled slug ΓåÆ typed not-found
        if (!problem) {
            throw new CodingProblemNotFoundException({
                identifier: slug,
            })
        }
        // persist a fresh submission in the pending state (verdict set later by the worker)
        const submission = await this.entityManager.save(CodingSubmissionEntity,
            {
                user: {
                    id: userId,
                },
                problem: {
                    id: problem.id,
                },
                language,
                sourceCode,
                verdict: CodingVerdict.Pending,
                // request metadata captured for device tracking below
                ipAddress,
                userAgent,
                deviceFingerprint: fingerprint,
            })
        // best-effort: remember the device this submission came from. The
        // submission row already exists at this point, so a failure here
        // must be swallowed (logged, not thrown) ΓÇö otherwise it would strand
        // an already-persisted Pending submission with no judging job ever
        // enqueued for it.
        try {
            await this.deviceService.recordDevice({
                userId,
                fingerprint,
                ipAddress,
                userAgent,
            })
        } catch (error) {
            const cause = error instanceof Error ? error : new Error(String(error))
            this.winstonService.log(WinstonLog.BestEffortOperationFailed,
                {
                    op: "coding.device-record.failed",
                    userId,
                    referenceId: submission.id,
                    error: cause.message,
                })
        }
        // enqueue the async judging job; the returned job id is what the client subscribes to
        const job = await this.enqueueJudgeCodingSubmissionJobService.enqueue({
            userId,
            codingSubmissionId: submission.id,
        })
        // hand back both ids so the resolver can return them to the client
        return {
            submissionId: submission.id,
            jobId: job.id,
        }
    }

    /**
     * Record that the user revealed a problem's reference solution. Idempotent
     * (one row per user+problem). Once recorded, a later first solve of that
     * problem awards no points ΓÇö peeking the answer forfeits the score.
     *
     * @param params - the viewing user's id + the problem slug
     * @returns whether a new reveal row was created (false when already revealed)
     * @throws CodingProblemNotFoundException when the slug is unknown/disabled
     */
    async recordSolutionReveal({
        userId,
        slug,
    }: RecordSolutionRevealParams): Promise<RecordSolutionRevealResult> {
        // resolve the target problem (must exist + be enabled) and load its reference
        // solutions ΓÇö this gated mutation is the ONLY place they are served to the client
        // (the problem detail read never carries them: not a GraphQL field, not indexed).
        const problem = await this.entityManager.findOne(CodingProblemEntity,
            {
                where: {
                    slug,
                    enabled: true,
                },
                relations: {
                    solutions: true,
                },
            })
        if (!problem) {
            throw new CodingProblemNotFoundException({
                identifier: slug,
            })
        }
        const solutions = problem.solutions ?? []
        // already revealed ΓåÆ idempotent: skip re-recording but still serve the answer
        const existing = await this.entityManager.findOne(CodingSolutionRevealEntity,
            {
                where: {
                    user: {
                        id: userId,
                    },
                    problem: {
                        id: problem.id,
                    },
                },
            })
        if (existing) {
            return {
                revealed: false,
                solutions,
            }
        }
        // first reveal ΓåÆ persist the forfeit marker
        await this.entityManager.save(CodingSolutionRevealEntity,
            {
                user: {
                    id: userId,
                },
                problem: {
                    id: problem.id,
                },
            })
        return {
            revealed: true,
            solutions,
        }
    }

    /**
     * Page a user's submissions for one problem, newest first.
     *
     * @param params - userId, slug, pagination
     * @returns the page of submissions + total count
     * @throws CodingProblemNotFoundException when the slug is unknown/disabled
     */
    async listMine({
        userId,
        slug,
        page = 1,
        limit = DEFAULT_PAGE_SIZE,
    }: ListMyCodingSubmissionsParams): Promise<ListMyCodingSubmissionsResult> {
        // resolve the problem id from the slug
        const problem = await this.entityManager.findOne(CodingProblemEntity,
            {
                where: {
                    slug,
                    enabled: true,
                },
            })
        // unknown/disabled slug ΓåÆ typed not-found
        if (!problem) {
            throw new CodingProblemNotFoundException({
                identifier: slug,
            })
        }
        // page the user's submissions for this problem, newest first
        const [submissions,
            total] = await this.entityManager.findAndCount(
            CodingSubmissionEntity,
            {
                // filter by the RELATION properties, not the read-only @RelationId
                // virtual columns (`userId`/`codingProblemId` aren't queryable and
                // throw EntityPropertyNotFoundError).
                where: {
                    user: {
                        id: userId,
                    },
                    problem: {
                        id: problem.id,
                    },
                },
                order: {
                    createdAt: "DESC",
                },
                skip: (page - 1) * limit,
                take: limit,
            },
        )
        return {
            submissions,
            total,
        }
    }

    /**
     * Read a target user's accepted-submission summary for one problem ΓÇö the
     * language(s) used across ALL accepted attempts, plus the testcase counts
     * and first-solve time from the EARLIEST accepted attempt. Backs the
     * public profile's `userCodingProblemDetail` read; deliberately hand-rolled
     * (never returns a raw {@link CodingSubmissionEntity}) so `sourceCode` /
     * `perCaseResults` / reference solutions can never leak through it.
     *
     * @param params - {@link GetAcceptedSubmissionSummaryParams}
     * @returns the summary, or null when the target user has no accepted submission for the problem
     */
    async getAcceptedSummary(
        {
            userId,
            problemId,
        }: GetAcceptedSubmissionSummaryParams,
    ): Promise<AcceptedSubmissionSummaryResult | null> {
        const rows = await this.entityManager.query<Array<AcceptedSubmissionSummaryRow>>(
            `
            WITH accepted AS (
                SELECT language, passed_count, total_count, created_at
                FROM coding_submissions
                WHERE user_id = $1 AND coding_problem_id = $2 AND verdict = 'accepted'
            )
            SELECT
                (SELECT array_agg(DISTINCT language::text) FROM accepted) AS languages,
                (SELECT passed_count FROM accepted ORDER BY created_at ASC LIMIT 1) AS passed_count,
                (SELECT total_count FROM accepted ORDER BY created_at ASC LIMIT 1) AS total_count,
                (SELECT MIN(created_at) FROM accepted) AS first_solved_at
            `,
            [
                userId,
                problemId,
            ],
        )
        const row = rows[0]
        // no accepted attempt for this user+problem ΓåÆ nothing to show
        if (!row?.first_solved_at) {
            return null
        }
        return {
            languages: row.languages ?? [],
            verdict: CodingVerdict.Accepted,
            passedCount: Number(row.passed_count) || 0,
            totalCount: Number(row.total_count) || 0,
            firstSolvedAt: row.first_solved_at,
        }
    }
}

import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
    MoreThanOrEqual,
    Not,
} from "typeorm"
import {
    FlashcardDueReviewSessionEntity,
    InjectPrimaryPostgreSQLEntityManager,
} from "@modules/databases"
import {
    UserService,
} from "../user"
import type {
    CompleteFlashcardDueReviewSessionParams,
    CompleteFlashcardDueReviewSessionResult,
    FindFlashcardDueReviewSessionByIdParams,
    FindMyInProgressFlashcardDueReviewSessionParams,
    MyInProgressFlashcardDueReviewSessionResultData,
    StartFlashcardDueReviewSessionParams,
    StartFlashcardDueReviewSessionResult,
    SyncFlashcardDueReviewSessionProgressParams,
    SyncFlashcardDueReviewSessionProgressResult,
} from "./types/flashcard-due-review-session"

/**
 * How far back a session's last sync may be for it to still be offered as
 * resumable ΓÇö same reasoning as `FlashcardReviewSessionService`'s own
 * `RESUME_WINDOW_HOURS`: a session synced longer ago than this is treated as
 * effectively abandoned even though `startFlashcardDueReviewSession` has not
 * yet flipped its status (that only happens when the SAME enrollment starts a
 * NEW draw).
 */
const RESUME_WINDOW_HOURS = 24

@Injectable()
/**
 * Business logic for the resumable CROSS-DECK due-review batch ("DueReview")
 * session ΓÇö mirrors
 * {@link import("./flashcard-review-session.service").FlashcardReviewSessionService}'s
 * resumable-draw shape, but scoped to an ENROLLMENT only (no deck): a
 * due-review batch draws cards across MULTIPLE decks in one course, so it
 * cannot reuse the deck-scoped review-session table/service. The actual SM-2
 * grading still happens per-card through the existing `reviewFlashcard`
 * mutation ({@link import("./flashcard-review.service").FlashcardReviewService.review});
 * this service is purely a resumable progress/bookkeeping wrapper around a
 * sequence of those calls, mirroring `FlashcardReviewSessionService`'s own XP
 * DECISION: `reviewFlashcard` grants no XP today, so `xpEarned` on
 * `flashcard_due_review_sessions` is a CLIENT-REPORTED BOOKKEEPING SNAPSHOT
 * ONLY ΓÇö `sync`/`complete` below persist whatever value the caller sends,
 * with NO `xp_histories` insert, NO `XpSource` addition, and NO daily-cap
 * logic.
 */
export class FlashcardDueReviewSessionService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly userService: UserService,
    ) {}

    /**
     * Persist ONE resumable due-review batch draw over a course, retiring any
     * PRIOR "in_progress" draw for the same enrollment first so a learner
     * never has two resumable due-review batches at once ΓÇö mirrors
     * `FlashcardReviewSessionService.start`'s own "abandon prior in_progress
     * row" step (there further scoped by deck; here scoped by enrollment
     * alone, since a due-review batch spans multiple decks).
     *
     * @param params - {@link StartFlashcardDueReviewSessionParams}
     * @returns the newly-persisted session's id.
     */
    async start(
        {
            userId,
            courseId,
            cardIds,
        }: StartFlashcardDueReviewSessionParams,
    ): Promise<StartFlashcardDueReviewSessionResult> {
        const enrollment = await this.userService.resolveOrCreateTrialEnrollment(
            userId,
            courseId,
        )

        // retire the enrollment's previous in-flight draw (if any) BEFORE
        // persisting the new one, so resume-lookup never has two candidates.
        await this.entityManager.update(
            FlashcardDueReviewSessionEntity,
            {
                enrollment: {
                    id: enrollment.id,
                },
                status: "in_progress",
            },
            {
                status: "abandoned",
            },
        )

        const session = await this.entityManager.save(
            FlashcardDueReviewSessionEntity,
            {
                enrollment,
                cardIds,
                currentIndex: 0,
                reviewedCount: 0,
                gradedIndexes: [],
                xpEarned: 0,
                status: "in_progress",
            },
        )

        return {
            sessionId: session.id,
        }
    }

    /**
     * Sync an in-flight due-review batch session's position + progress ΓÇö
     * ownership-scoped, silently no-ops (never throws) for a session that is
     * not found/owned or no longer "in_progress", same reasoning as
     * `FlashcardReviewSessionService.sync` (a background periodic sync must
     * never surface an error toast mid-batch).
     *
     * @param params - {@link SyncFlashcardDueReviewSessionProgressParams}
     * @returns whether the sync was applied.
     */
    async sync(
        {
            userId,
            sessionId,
            currentIndex,
            reviewedCount,
            gradedIndexes,
            xpEarned,
        }: SyncFlashcardDueReviewSessionProgressParams,
    ): Promise<SyncFlashcardDueReviewSessionProgressResult> {
        const session = await this.entityManager.findOne(
            FlashcardDueReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
                select: {
                    id: true,
                    status: true,
                },
            },
        )

        if (!session || session.status !== "in_progress") {
            return {
                success: false,
            }
        }

        await this.entityManager.update(
            FlashcardDueReviewSessionEntity,
            {
                id: session.id,
            },
            {
                currentIndex,
                reviewedCount,
                // only overwrite the graded-index set when the caller sent one
                // ΓÇö omitting it must leave the column untouched (same tolerance
                // the rest of the sync payload has), not wipe it to undefined.
                ...(gradedIndexes !== undefined ? {
                    gradedIndexes,
                } : {
                }),
                xpEarned,
            },
        )

        return {
            success: true,
        }
    }

    /**
     * Record a finished due-review batch session ΓÇö flips the row to
     * "completed" and snapshots the final reviewed-count/xpEarned the caller
     * reports. Ownership-scoped via `status: Not("completed")` (loosened
     * 2026-07-12 ΓÇö was `status: "in_progress"`, mirroring
     * `FlashcardReviewSessionService.complete`'s own guard): the STRICT
     * `"in_progress"` match silently updated ZERO rows (TypeORM `update()`
     * never throws on a no-match) whenever the row had ALREADY been raced to
     * "abandoned" by a concurrent `start()` (retires every prior in_progress
     * row for the enrollment ΓÇö e.g. a duplicate resolve-or-start effect fire)
     * BEFORE this call landed ΓÇö the FE still reported "success" (the mutation
     * itself never errored), but the row was permanently stuck un-completed,
     * so a later revisit-by-URL/resume kept re-entering the review instead of
     * showing the recap (thß║ºy 2026-07-12: after finishing, F5 must show the
     * recap, not the last flashcard again). `Not("completed")` still refuses to re-flip an
     * ALREADY-completed row (replay-safe, same as before) while tolerating
     * "abandoned" ΓÇö the learner genuinely finished, so their completion
     * should win regardless of what else raced the row's status meanwhile.
     *
     * NO XP is granted here ΓÇö see the class doc's XP DECISION. `xpEarned` is
     * echoed straight through as a bookkeeping snapshot, never written to
     * `xp_histories`.
     *
     * @param params - {@link CompleteFlashcardDueReviewSessionParams}
     * @returns the reviewed-count/xpEarned snapshotted onto the row.
     */
    async complete(
        {
            userId,
            sessionId,
            reviewedCount,
            xpEarned,
        }: CompleteFlashcardDueReviewSessionParams,
    ): Promise<CompleteFlashcardDueReviewSessionResult> {
        // Ownership is a two-level nested relation (enrollment ΓåÆ user), which a
        // bare `update()` cannot express: TypeORM compiles `update` to an
        // UpdateQueryBuilder that has no JOINs, so a nested-relation WHERE throws
        // "Cannot find alias for relation". Resolve ownership with a `findOne`
        // (which CAN join) first, then update by the scalar `id` + the
        // replay-safe `status` guard ΓÇö mirroring `sync()` in this same service.
        const owned = await this.entityManager.findOne(
            FlashcardDueReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
                select: {
                    id: true,
                },
            },
        )
        if (owned) {
            await this.entityManager.update(
                FlashcardDueReviewSessionEntity,
                {
                    id: sessionId,
                    status: Not("completed"),
                },
                {
                    status: "completed",
                    reviewedCount,
                    xpEarned,
                },
            )
        }

        return {
            reviewedCount,
            xpEarned,
        }
    }

    /**
     * Find the most recent `status = "in_progress"` due-review batch session,
     * synced within {@link RESUME_WINDOW_HOURS}, for the caller's enrollment
     * in one course ΓÇö mirrors
     * `MyInProgressFlashcardQuizSessionService.find`/
     * `FlashcardReviewSessionService.findInProgress`, scoped by course
     * (course-wide, like quiz sessions ΓÇö NOT per-deck, unlike review
     * sessions).
     *
     * @param params - {@link FindMyInProgressFlashcardDueReviewSessionParams}
     * @returns the resumable session, or null when there is none.
     */
    async findInProgress(
        {
            userId,
            courseId,
        }: FindMyInProgressFlashcardDueReviewSessionParams,
    ): Promise<MyInProgressFlashcardDueReviewSessionResultData | null> {
        const enrollment = await this.userService.resolveOrCreateTrialEnrollment(
            userId,
            courseId,
        )

        const resumeWindowStart = new Date(
            Date.now() - RESUME_WINDOW_HOURS * 60 * 60 * 1000,
        )

        const session = await this.entityManager.findOne(
            FlashcardDueReviewSessionEntity,
            {
                where: {
                    enrollment: {
                        id: enrollment.id,
                    },
                    status: "in_progress",
                    updatedAt: MoreThanOrEqual(resumeWindowStart),
                },
                order: {
                    updatedAt: "DESC",
                },
            },
        )

        if (!session) {
            return null
        }

        return {
            sessionId: session.id,
            cardIds: session.cardIds,
            currentIndex: session.currentIndex,
            reviewedCount: session.reviewedCount,
            gradedIndexes: session.gradedIndexes ?? [],
            xpEarned: session.xpEarned,
            updatedAt: session.updatedAt,
        }
    }

    /**
     * Find a due-review batch session directly by its id (ownership-checked
     * against the caller) ΓÇö mirrors
     * `FlashcardReviewSessionService.findById`; no deck identity to attach
     * here (a due-review batch spans multiple decks, per-card deckId comes
     * from the drawn cards themselves, not the session row). NOT
     * window/status-scoped like `findInProgress` ΓÇö a direct link to a
     * completed/abandoned session still resolves.
     *
     * @param params - {@link FindFlashcardDueReviewSessionByIdParams}
     * @returns the session, or null when not found/not owned by the caller.
     */
    async findById(
        {
            userId,
            sessionId,
        }: FindFlashcardDueReviewSessionByIdParams,
    ): Promise<MyInProgressFlashcardDueReviewSessionResultData | null> {
        const session = await this.entityManager.findOne(
            FlashcardDueReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
            },
        )

        if (!session) {
            return null
        }

        return {
            sessionId: session.id,
            cardIds: session.cardIds,
            currentIndex: session.currentIndex,
            reviewedCount: session.reviewedCount,
            gradedIndexes: session.gradedIndexes ?? [],
            xpEarned: session.xpEarned,
            updatedAt: session.updatedAt,
        }
    }
}

import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
    In,
    MoreThanOrEqual,
    Not,
} from "typeorm"
import {
    FlashcardDeckEntity,
    FlashcardReviewSessionEntity,
    InjectPrimaryPostgreSQLEntityManager,
    UserFlashcardReviewEntity,
} from "@modules/databases"
import {
    FlashcardDeckNotFoundException,
} from "@modules/exceptions"
import {
    UserService,
} from "../user"
import type {
    CompleteFlashcardReviewSessionParams,
    CompleteFlashcardReviewSessionResult,
    FindFlashcardReviewSessionByIdParams,
    FindMyInProgressFlashcardReviewSessionParams,
    FlashcardReviewSessionByIdResultData,
    MyInProgressFlashcardReviewSessionResultData,
    StartFlashcardReviewSessionParams,
    StartFlashcardReviewSessionResult,
    SyncFlashcardReviewSessionProgressParams,
    SyncFlashcardReviewSessionProgressResult,
} from "./types/flashcard-review-session"

/**
 * How far back a session's last sync may be for it to still be offered as
 * resumable ΓÇö same reasoning as `MyInProgressFlashcardQuizSessionService`'s
 * own `RESUME_WINDOW_HOURS`: a session synced longer ago than this is treated
 * as effectively abandoned even though `startFlashcardReviewSession` has not
 * yet flipped its status (that only happens when the SAME enrollment+deck
 * starts a NEW draw).
 */
const RESUME_WINDOW_HOURS = 24

@Injectable()
/**
 * Business logic for the resumable flashcard reviewer session ΓÇö
 * mirrors {@link import("./flashcard-quiz-session.service").FlashcardQuizSessionService}'s
 * resumable-draw shape, but scoped to ONE deck (not a whole course) and with
 * NO coverage/weakTags/XP-grant complexity: the actual SM-2 grading still
 * happens per-card through the existing `reviewFlashcard` mutation
 * ({@link import("./flashcard-review.service").FlashcardReviewService.review}); this
 * service is purely a resumable progress/bookkeeping wrapper around a
 * sequence of those calls, so history/stats can be built for review mode the
 * same way they already exist for quiz mode.
 *
 * XP DECISION: `reviewFlashcard` grants no XP today and writes no
 * `xp_histories` row. To avoid inventing a new, unreviewed XP-granting
 * mechanism for this MVP pass, `xpEarned` on `flashcard_review_sessions` is
 * treated as a CLIENT-REPORTED BOOKKEEPING SNAPSHOT ONLY ΓÇö `sync`/`complete`
 * below persist whatever value the caller sends, with NO `xp_histories`
 * insert, NO `XpSource` addition, and NO daily-cap logic. This keeps parity
 * with `reviewFlashcard`'s own current behavior (no XP) instead of silently
 * introducing a parallel economy.
 */
export class FlashcardReviewSessionService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly userService: UserService,
    ) {}

    /**
     * Persist ONE resumable flashcard review session draw over a single deck,
     * retiring any PRIOR "in_progress" draw for the same enrollment+deck first
     * so a learner never has two resumable review sessions on the same deck
     * at once ΓÇö mirrors `FlashcardQuizSessionService`'s own "abandon prior
     * in_progress row" step (there scoped by enrollment alone; here further
     * scoped by deck, since review sessions are per-deck).
     *
     * @param params - {@link StartFlashcardReviewSessionParams}
     * @returns the newly-persisted session's id.
     * @throws FlashcardDeckNotFoundException when the deck does not exist.
     */
    async start(
        {
            userId,
            deckId,
            cardIds,
            mode = "full",
        }: StartFlashcardReviewSessionParams,
    ): Promise<StartFlashcardReviewSessionResult> {
        const deck = await this.entityManager.findOne(
            FlashcardDeckEntity,
            {
                where: {
                    id: deckId,
                },
                select: {
                    id: true,
                    course: {
                        id: true,
                    },
                },
                relations: {
                    course: true,
                },
            },
        )
        if (!deck) {
            throw new FlashcardDeckNotFoundException({
                flashcardDeckId: deckId,
            })
        }

        // Due-only mode (thß║ºy 2026-07-13): narrow the requested cardIds down to
        // the ones actually DUE ΓÇö no review row yet (never learned) OR past their
        // `due_at`. Same predicate as `FlashcardDeckService.annotateViewerStats`'
        // `dueCount` (keyed by user_id so the count shown on the deck card and the
        // set persisted here match exactly), and the whole point of the due-only
        // mode: cards graded Good/Easy recently (due_at in the future) drop out.
        // A filter that would leave NOTHING keeps the full set ΓÇö never persist an
        // empty draw (the modal already disables this mode when dueCount is 0, so
        // this is only a defensive floor).
        let effectiveCardIds = cardIds
        if (mode === "due") {
            const now = new Date()
            const reviews = await this.entityManager.find(
                UserFlashcardReviewEntity,
                {
                    where: {
                        userId,
                        flashcardCard: {
                            id: In(cardIds),
                        },
                    },
                    select: {
                        dueAt: true,
                        flashcardCard: {
                            id: true,
                        },
                    },
                    relations: {
                        flashcardCard: true,
                    },
                },
            )
            const dueAtByCardId = new Map<string, Date | null>()
            for (const review of reviews) {
                dueAtByCardId.set(review.flashcardCard.id,
                    review.dueAt)
            }
            const dueCardIds = cardIds.filter((id) => {
                // a card with NO review row was never in the map ΓåÆ never reviewed ΓåÆ due.
                // `has` distinguishes that from a row whose `dueAt` is null.
                if (!dueAtByCardId.has(id)) {
                    return true
                }
                const dueAt = dueAtByCardId.get(id)
                // a null due_at (unscheduled) counts as due; else due when past due_at
                return !dueAt || dueAt <= now
            })
            if (dueCardIds.length > 0) {
                effectiveCardIds = dueCardIds
            }
        }

        // review sessions are anchored to the SAME (user, course) trial
        // enrollment startFlashcardQuizSession/reviewFlashcard already resolve
        // ΓÇö the course is derived from the deck itself since the request only
        // carries deckId, not courseId.
        const enrollment = await this.userService.resolveOrCreateTrialEnrollment(
            userId,
            deck.course.id,
        )

        // retire the enrollment+deck's previous in-flight draw (if any) BEFORE
        // persisting the new one, so resume-lookup never has two candidates.
        await this.entityManager.update(
            FlashcardReviewSessionEntity,
            {
                enrollment: {
                    id: enrollment.id,
                },
                deck: {
                    id: deckId,
                },
                status: "in_progress",
            },
            {
                status: "abandoned",
            },
        )

        const session = await this.entityManager.save(
            FlashcardReviewSessionEntity,
            {
                enrollment,
                deck: {
                    id: deckId,
                },
                cardIds: effectiveCardIds,
                currentIndex: 0,
                reviewedCount: 0,
                gradedIndexes: [],
                xpEarned: 0,
                status: "in_progress",
            },
        )

        return {
            sessionId: session.id,
        }
    }

    /**
     * Sync an in-flight flashcard review session's position + progress ΓÇö
     * ownership-scoped, silently no-ops (never throws) for a session that is
     * not found/owned or no longer "in_progress", same reasoning as
     * `SyncFlashcardQuizSessionProgressHandler` (a background periodic sync
     * must never surface an error toast mid-review).
     *
     * @param params - {@link SyncFlashcardReviewSessionProgressParams}
     * @returns whether the sync was applied.
     */
    async sync(
        {
            userId,
            sessionId,
            currentIndex,
            reviewedCount,
            gradedIndexes,
            xpEarned,
        }: SyncFlashcardReviewSessionProgressParams,
    ): Promise<SyncFlashcardReviewSessionProgressResult> {
        const session = await this.entityManager.findOne(
            FlashcardReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
                select: {
                    id: true,
                    status: true,
                },
            },
        )

        if (!session || session.status !== "in_progress") {
            return {
                success: false,
            }
        }

        await this.entityManager.update(
            FlashcardReviewSessionEntity,
            {
                id: session.id,
            },
            {
                currentIndex,
                reviewedCount,
                // only overwrite the graded-index set when the caller sent one
                // ΓÇö omitting it must leave the column untouched (same tolerance
                // the rest of the sync payload has), not wipe it to undefined.
                ...(gradedIndexes !== undefined ? {
                    gradedIndexes,
                } : {
                }),
                xpEarned,
            },
        )

        return {
            success: true,
        }
    }

    /**
     * Record a finished flashcard review session ΓÇö flips the row to
     * "completed" and snapshots the final reviewed-count/xpEarned the caller
     * reports. Ownership-scoped via `status: Not("completed")` (loosened
     * 2026-07-12 ΓÇö was `status: "in_progress"`; see
     * `FlashcardDueReviewSessionService.complete`'s own doc for the full
     * root-cause: a STRICT `"in_progress"` match silently updates ZERO rows
     * ΓÇö no throw ΓÇö whenever the row got raced to "abandoned" by a concurrent
     * `start()` first, permanently stranding the session un-completed even
     * though the FE mutation call itself reported success). `Not("completed")`
     * stays replay-safe (refuses to re-flip an already-completed row) while
     * tolerating a raced "abandoned" status.
     *
     * NO XP is granted here ΓÇö see the class doc's XP DECISION. `xpEarned` is
     * echoed straight through as a bookkeeping snapshot, never written to
     * `xp_histories`.
     *
     * @param params - {@link CompleteFlashcardReviewSessionParams}
     * @returns the reviewed-count/xpEarned snapshotted onto the row.
     */
    async complete(
        {
            userId,
            sessionId,
            reviewedCount,
            xpEarned,
        }: CompleteFlashcardReviewSessionParams,
    ): Promise<CompleteFlashcardReviewSessionResult> {
        // Ownership is a two-level nested relation (enrollment ΓåÆ user), which a
        // bare `update()` cannot express: TypeORM compiles `update` to an
        // UpdateQueryBuilder that has no JOINs, so a nested-relation WHERE throws
        // "Cannot find alias for relation". Resolve ownership with a `findOne`
        // (which CAN join) first, then update by the scalar `id` + the
        // replay-safe `status` guard ΓÇö mirroring `sync()` in this same service.
        const owned = await this.entityManager.findOne(
            FlashcardReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
                select: {
                    id: true,
                },
            },
        )
        if (owned) {
            await this.entityManager.update(
                FlashcardReviewSessionEntity,
                {
                    id: sessionId,
                    status: Not("completed"),
                },
                {
                    status: "completed",
                    reviewedCount,
                    xpEarned,
                },
            )
        }

        return {
            reviewedCount,
            xpEarned,
        }
    }

    /**
     * Find the most recent `status = "in_progress"` review session, synced
     * within {@link RESUME_WINDOW_HOURS}, for the caller's enrollment scoped
     * to ONE deck ΓÇö mirrors `MyInProgressFlashcardQuizSessionService.find`,
     * further scoped by deck (review sessions are per-deck, quiz sessions are
     * per-course).
     *
     * @param params - {@link FindMyInProgressFlashcardReviewSessionParams}
     * @returns the resumable session, or null when there is none.
     * @throws FlashcardDeckNotFoundException when the deck does not exist.
     */
    async findInProgress(
        {
            userId,
            deckId,
        }: FindMyInProgressFlashcardReviewSessionParams,
    ): Promise<MyInProgressFlashcardReviewSessionResultData | null> {
        const deck = await this.entityManager.findOne(
            FlashcardDeckEntity,
            {
                where: {
                    id: deckId,
                },
                select: {
                    id: true,
                    course: {
                        id: true,
                    },
                },
                relations: {
                    course: true,
                },
            },
        )
        if (!deck) {
            throw new FlashcardDeckNotFoundException({
                flashcardDeckId: deckId,
            })
        }

        const enrollment = await this.userService.resolveOrCreateTrialEnrollment(
            userId,
            deck.course.id,
        )

        const resumeWindowStart = new Date(
            Date.now() - RESUME_WINDOW_HOURS * 60 * 60 * 1000,
        )

        const session = await this.entityManager.findOne(
            FlashcardReviewSessionEntity,
            {
                where: {
                    enrollment: {
                        id: enrollment.id,
                    },
                    deck: {
                        id: deckId,
                    },
                    status: "in_progress",
                    updatedAt: MoreThanOrEqual(resumeWindowStart),
                },
                order: {
                    updatedAt: "DESC",
                },
            },
        )

        if (!session) {
            return null
        }

        return {
            sessionId: session.id,
            cardIds: session.cardIds,
            currentIndex: session.currentIndex,
            reviewedCount: session.reviewedCount,
            gradedIndexes: session.gradedIndexes ?? [],
            xpEarned: session.xpEarned,
            updatedAt: session.updatedAt,
        }
    }

    /**
     * Find a review session directly by its id (ownership-checked against the
     * caller) ΓÇö no `deckId` needed upfront, unlike {@link findInProgress}. The
     * FE's unified `/review/sessions/[sessionId]` route uses this to resolve
     * full context (deck + progress) from just the id in the URL (thß║ºy
     * 2026-07-11: session already persists everything ΓÇö no `deckId` query hint
     * needed). NOT window/status-scoped like `findInProgress` ΓÇö a direct link
     * to a completed/abandoned session still resolves (so a stale link shows
     * the real state instead of a false 404); the caller decides what to do
     * with a non-"in_progress" row.
     *
     * @param params - {@link FindFlashcardReviewSessionByIdParams}
     * @returns the session with its deck identity attached, or null when not
     * found/not owned by the caller.
     */
    async findById(
        {
            userId,
            sessionId,
        }: FindFlashcardReviewSessionByIdParams,
    ): Promise<FlashcardReviewSessionByIdResultData | null> {
        const session = await this.entityManager.findOne(
            FlashcardReviewSessionEntity,
            {
                where: {
                    id: sessionId,
                    enrollment: {
                        user: {
                            id: userId,
                        },
                    },
                },
                relations: {
                    deck: true,
                },
            },
        )

        if (!session) {
            return null
        }

        return {
            sessionId: session.id,
            deckId: session.deckId,
            deckTitle: session.deck.title,
            cardIds: session.cardIds,
            currentIndex: session.currentIndex,
            reviewedCount: session.reviewedCount,
            gradedIndexes: session.gradedIndexes ?? [],
            xpEarned: session.xpEarned,
            updatedAt: session.updatedAt,
        }
    }
}

import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
    In,
} from "typeorm"
import {
    EnrollmentEntity,
    FlashcardCardEntity,
    FlashcardDeckEntity,
    FlashcardDeckResolverService,
    FlashcardReviewEventEntity,
    InjectPrimaryPostgreSQLEntityManager,
    Locale,
    UserFlashcardReviewEntity,
    XpSource,
} from "@modules/databases"
import {
    FlashcardCardNotFoundException,
} from "@modules/exceptions"
import {
    FLAT_POINTS,
    writeXpHistory,
} from "@features/api/processors/ai/shared/xp"
import {
    UserService,
} from "../user"
import type {
    ApplySm2Params,
    ApplySm2Result,
    DueCardIdRow,
    DueFlashcard,
    DueFlashcardsResult,
    FlashcardNextIntervals,
    ListDueFlashcardsParams,
    ListFlashcardsByIdsParams,
    ReviewFlashcardParams,
    ReviewFlashcardResult,
} from "./types/flashcard-review"

/** Default SM-2 scheduling state for a card the viewer has never reviewed. */
export const NEW_CARD_STATE: Omit<ApplySm2Params, "grade"> = {
    prevEase: 2.5,
    prevInterval: 0,
    prevRepetitions: 0,
}

/** SM-2 grade value for "Again" (a lapse ΓåÆ reset). */
const GRADE_AGAIN = 0

/**
 * Per-course weighted XP granted the FIRST time a user ever grades a given card
 * (mirrors `mark-as-readed`'s `LESSON_READ_XP`). Repeat reviews grant nothing ΓÇö
 * the reward is for turning up a NEW card, not for re-drilling a known one.
 */
const FLASHCARD_FIRST_REVIEW_XP = 2

/** Lower bound the SM-2 easiness factor may never drop below. */
const EASE_FLOOR = 1.3

/**
 * Max NEW (never-reviewed) cards offered per "due today" batch. Caps the
 * headline so a fresh viewer sees a manageable batch (overdue reviews + this
 * many new) instead of the entire never-reviewed backlog (the "449" bug). The
 * batch refills as new cards get reviewed and leave the new pool.
 */
const DAILY_NEW_LIMIT = 20

@Injectable()
/**
 * Spaced-repetition (SM-2) read + write for flashcards. {@link listDue} serves
 * the viewer's due-card queue (no review row yet OR past its `dueAt`) across all
 * decks ΓÇö enrollment is NOT required, so trial viewers can review too; {@link review}
 * applies an SM-2 grade and upserts the per-(user, card) review row.
 */
export class FlashcardReviewService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly flashcardDeckResolver: FlashcardDeckResolverService,
        private readonly userService: UserService,
    ) {}

    /**
     * List the viewer's due flashcards. A card is due when it has no review row
     * yet OR its review `dueAt <= now()`, and its deck belongs to a course the
     * viewer is enrolled in. Returns the total due count plus the first `limit`
     * cards, localized to the request locale.
     *
     * @param params - {@link ListDueFlashcardsParams}
     * @returns the due count + first page of localized cards.
     */
    async listDue(
        {
            userId,
            courseId,
            limit,
            locale,
        }: ListDueFlashcardsParams,
    ): Promise<DueFlashcardsResult> {
        // On a COURSE page, the review row is keyed by ENROLLMENT (the anchor for
        // per-course progress going forward) ΓÇö resolve the viewer's enrollment id for
        // this course READ-ONLY (no trial create on a read; a viewer with no enrollment
        // simply has no review rows ΓåÆ every card reads as NEW). The DASHBOARD (global)
        // queue spans every course, so it keeps keying the review by user_id (a single
        // enrollment id does not exist across courses).
        const enrollmentId = courseId
            ? (
                await this.entityManager.findOne(
                    EnrollmentEntity,
                    {
                        where: {
                            user: {
                                id: userId,
                            },
                            course: {
                                id: courseId,
                            },
                        },
                        select: {
                            id: true,
                        },
                    },
                )
            )?.id ?? null
            : null

        // shared scaffold: card ΓåÆ deck SCOPED TO THE COURSE (the due count on
        // a course page must reflect only that course's decks, not every deck
        // system-wide), with the per-viewer review row left-joined. Enrollment is NOT
        // required ΓÇö trial viewers review flashcards too. The review join keys by
        // enrollment_id on a course page (and by user_id on the global dashboard queue).
        const base = () => {
            const reviewJoin = courseId
                ? "review.flashcard_card_id = card.id AND review.enrollment_id = :enrollmentId"
                : "review.flashcard_card_id = card.id AND review.user_id = :userId"
            const qb = this.entityManager
                .createQueryBuilder(FlashcardCardEntity,
                    "card")
                .innerJoin(FlashcardDeckEntity,
                    "deck",
                    "deck.id = card.flashcard_deck_id")
                .leftJoin(
                    UserFlashcardReviewEntity,
                    "review",
                    reviewJoin,
                    {
                        userId,
                        enrollmentId,
                    },
                )
            // scope to one course on a course page; omit ΓåÆ global queue (dashboard)
            if (courseId) {
                qb.andWhere("deck.course_id = :courseId",
                    {
                        courseId,
                    })
            }
            return qb
        }

        // Split "due" into its two semantically-different buckets instead of lumping
        // never-reviewed cards into "due today" (that made a fresh viewer see the
        // whole backlog as due ΓÇö the "449" bug).
        //  - overdue REVIEW = already learned once, now past dueAt
        //  - NEW = never reviewed; capped to DAILY_NEW_LIMIT for "today"
        const OVERDUE = "review.id IS NOT NULL AND review.due_at <= now()"
        const NEW = "review.id IS NULL"
        const dueReviewCount = await base().andWhere(OVERDUE).getCount()
        const newTotalCount = await base().andWhere(NEW).getCount()
        const newCount = Math.min(newTotalCount,
            DAILY_NEW_LIMIT)
        const dueCount = dueReviewCount + newCount

        // page: overdue first (oldest-due first), then fill the rest with today's
        // capped new batch ΓÇö so reviews never starve behind new cards.
        const SELECT_COLS = (qb: ReturnType<typeof base>) => qb
            .select("card.id",
                "card_id")
            .addSelect("review.ease",
                "review_ease")
            .addSelect("review.intervalDays",
                "review_interval_days")
            .addSelect("review.repetitions",
                "review_repetitions")
        const overdueRows = await SELECT_COLS(base().andWhere(OVERDUE))
            .orderBy("review.due_at",
                "ASC")
            .addOrderBy("card.id",
                "ASC")
            .limit(limit)
            .getRawMany<DueCardIdRow>()
        const newSlots = Math.min(newCount,
            Math.max(0,
                limit - overdueRows.length))
        const newRows = newSlots > 0
            ? await SELECT_COLS(base().andWhere(NEW))
                .orderBy("card.id",
                    "ASC")
                .limit(newSlots)
                .getRawMany<DueCardIdRow>()
            : []
        const rows = [
            ...overdueRows,
            ...newRows,
        ]

        const cardIds = rows.map((row) => row.card_id)
        // map each due card to its prior SM-2 state (defaults for a brand-new card)
        const priorByCardId = new Map<string, Omit<ApplySm2Params, "grade">>()
        for (const row of rows) {
            priorByCardId.set(row.card_id,
                {
                    prevEase: row.review_ease ?? NEW_CARD_STATE.prevEase,
                    prevInterval: row.review_interval_days ?? NEW_CARD_STATE.prevInterval,
                    prevRepetitions: row.review_repetitions ?? NEW_CARD_STATE.prevRepetitions,
                })
        }
        if (cardIds.length === 0) {
            return {
                dueCount,
                dueReviewCount,
                newCount,
                newTotalCount,
                cards: [],
            }
        }

        // load the full card graph (deck + both their translations) for the page
        const cards = await this.entityManager.find(
            FlashcardCardEntity,
            {
                where: {
                    id: In(cardIds),
                },
                relations: {
                    deck: {
                        translations: true,
                    },
                    translations: true,
                },
            },
        )
        // localize each card via its deck (the deck resolver localizes the deck
        // title AND recurses into the card front/back). Localize once per distinct
        // deck so a shared deck is not transformed twice.
        const localizedDeckTitleById = new Map<string, string>()
        const cardById = new Map<string, FlashcardCardEntity>()
        for (const card of cards) {
            const deck = card.deck
            if (deck && !localizedDeckTitleById.has(deck.id)) {
                // clone-free in-place localize: load just THIS card under the deck so
                // the resolver localizes both the deck title and the card text
                deck.cards = [
                    card,
                ]
                this.flashcardDeckResolver.transform(
                    deck,
                    locale,
                    deck.defaultLocale ?? Locale.En,
                )
                localizedDeckTitleById.set(deck.id,
                    deck.title)
            }
            cardById.set(card.id,
                card)
        }

        // Gate premium answers behind enrollment, mirroring the content paywall's
        // isEntitled/lockPremiumContent pair (`content.handler.ts:174-184`) ΓÇö this
        // is the enforcement `FlashcardCardEntity.isPremium`'s own doc claims exists
        // but never did (see `.artifacts/states/flashcard/findings.md` #1). The
        // GLOBAL (cross-course) queue can mix cards from many courses, so entitlement
        // is resolved per the CARD'S OWN course (`card.deck.courseId`), not the
        // request's optional `courseId` ΓÇö cached per distinct course id so a shared
        // course is only checked once.
        const entitledByCourseId = await this.resolveEntitlementByCourseId(
            cards,
            userId,
        )

        // preserve the due-order page ordering (find does not guarantee it)
        const localized: Array<DueFlashcard> = cardIds
            .map((id) => cardById.get(id))
            .filter((card): card is FlashcardCardEntity => Boolean(card))
            .map((card) => ({
                cardId: card.id,
                deckTitle: card.deck
                    ? (localizedDeckTitleById.get(card.deck.id) ?? card.deck.title)
                    : "",
                front: card.question,
                back: this.isEntitledToCard(card,
                    entitledByCourseId)
                    ? (card.answer ?? "")
                    : "",
                level: card.level ?? null,
                tags: card.tags ?? [],
                nextIntervals: this.previewIntervals(
                    priorByCardId.get(card.id) ?? NEW_CARD_STATE,
                ),
            }))
        return {
            dueCount,
            dueReviewCount,
            newCount,
            newTotalCount,
            cards: localized,
        }
    }

    /**
     * List flashcards by an EXACT set of ids, regardless of current due status ΓÇö
     * unlike {@link listDue}, a card graded (and so no longer "due") since the
     * batch was drawn is NOT dropped. Rehydrates a resumable due-review batch to
     * its ORIGINAL draw: a `DueReviewSession`'s persisted `cardIds` intersected
     * against a fresh `listDue` call shrinks every time a card in it gets graded
     * (its `dueAt` moves to the future) ΓÇö a small/near-finished batch easily hits
     * zero overlap on the very next visit, silently discarding a legitimately
     * in-progress session and starting a new one (thß║ºy 2026-07-11: due review
     * must not silently open a new session). Output order matches `cardIds` (a card id that no
     * longer exists is simply dropped, not errored).
     *
     * @param params - {@link ListFlashcardsByIdsParams}
     * @returns the requested cards, localized, in `cardIds` order.
     */
    async listByIds(
        {
            userId,
            courseId,
            cardIds,
            locale,
        }: ListFlashcardsByIdsParams,
    ): Promise<Array<DueFlashcard>> {
        if (cardIds.length === 0) {
            return []
        }

        // same enrollment-vs-user review-row keying as `listDue` (course page ΓåÆ
        // enrollment; no course context ΓåÆ user-wide).
        const enrollmentId = courseId
            ? (
                await this.entityManager.findOne(
                    EnrollmentEntity,
                    {
                        where: {
                            user: {
                                id: userId,
                            },
                            course: {
                                id: courseId,
                            },
                        },
                        select: {
                            id: true,
                        },
                    },
                )
            )?.id ?? null
            : null

        // a course-scoped call with NO resolved enrollment has no course-scoped
        // review rows to find (mirrors `listDue`'s raw-SQL `review.enrollment_id
        // = :enrollmentId` with a null param ΓÇö always zero rows) ΓÇö skip the
        // query rather than pass `undefined` into the `where`, which TypeORM
        // reads as "no filter on this field" and would match every OTHER
        // user's enrollment-scoped reviews instead of none.
        const reviews = courseId && !enrollmentId
            ? []
            : await this.entityManager.find(
                UserFlashcardReviewEntity,
                {
                    where: courseId
                        ? {
                            flashcardCard: {
                                id: In(cardIds),
                            },
                            enrollment: {
                                id: enrollmentId as string,
                            },
                        }
                        : {
                            flashcardCard: {
                                id: In(cardIds),
                            },
                            user: {
                                id: userId,
                            },
                        },
                    select: {
                        ease: true,
                        intervalDays: true,
                        repetitions: true,
                        flashcardCard: {
                            id: true,
                        },
                    },
                    relations: {
                        flashcardCard: true,
                    },
                },
            )
        const priorByCardId = new Map<string, Omit<ApplySm2Params, "grade">>()
        for (const review of reviews) {
            priorByCardId.set(review.flashcardCard.id,
                {
                    prevEase: review.ease ?? NEW_CARD_STATE.prevEase,
                    prevInterval: review.intervalDays ?? NEW_CARD_STATE.prevInterval,
                    prevRepetitions: review.repetitions ?? NEW_CARD_STATE.prevRepetitions,
                })
        }

        // load + localize exactly like `listDue`'s tail (deck + translations,
        // localize once per distinct deck).
        const cards = await this.entityManager.find(
            FlashcardCardEntity,
            {
                where: {
                    id: In(cardIds),
                },
                relations: {
                    deck: {
                        translations: true,
                    },
                    translations: true,
                },
            },
        )
        const localizedDeckTitleById = new Map<string, string>()
        const cardById = new Map<string, FlashcardCardEntity>()
        for (const card of cards) {
            const deck = card.deck
            if (deck && !localizedDeckTitleById.has(deck.id)) {
                deck.cards = [
                    card,
                ]
                this.flashcardDeckResolver.transform(
                    deck,
                    locale,
                    deck.defaultLocale ?? Locale.En,
                )
                localizedDeckTitleById.set(deck.id,
                    deck.title)
            }
            cardById.set(card.id,
                card)
        }

        // Gate premium answers behind enrollment ΓÇö same rationale as `listDue`
        // (see the comment there); this batch can likewise mix cards drawn from
        // several courses (a resumed cross-course due-review batch).
        const entitledByCourseId = await this.resolveEntitlementByCourseId(
            cards,
            userId,
        )

        return cardIds
            .map((id) => cardById.get(id))
            .filter((card): card is FlashcardCardEntity => Boolean(card))
            .map((card) => ({
                cardId: card.id,
                deckTitle: card.deck
                    ? (localizedDeckTitleById.get(card.deck.id) ?? card.deck.title)
                    : "",
                front: card.question,
                back: this.isEntitledToCard(card,
                    entitledByCourseId)
                    ? (card.answer ?? "")
                    : "",
                level: card.level ?? null,
                tags: card.tags ?? [],
                nextIntervals: this.previewIntervals(
                    priorByCardId.get(card.id) ?? NEW_CARD_STATE,
                ),
            }))
    }

    /**
     * Apply an SM-2 grade to a card for a user and upsert the review row.
     *
     * SM-2: on Again (0) reset repetitions to 0 and interval to 1 day; otherwise
     * repetitions++, ease = max(1.3, ease + (0.1 - (3-grade)*(0.08+(3-grade)*0.02))),
     * interval = rep==1 ? 1 : rep==2 ? 6 : round(prevInterval * ease).
     * `dueAt` = now + interval days.
     *
     * @param params - {@link ReviewFlashcardParams}
     * @returns the next due date.
     * @throws FlashcardCardNotFoundException when the card does not exist.
     */
    async review(
        {
            userId,
            cardId,
            grade,
            sessionId,
        }: ReviewFlashcardParams,
    ): Promise<ReviewFlashcardResult> {
        return this.entityManager.transaction(async (manager) => {
            // the card must exist (FK target) ΓÇö a typed 404 otherwise. Load its deck
            // so we can derive the course (card ΓåÆ deck ΓåÆ course) and key the review
            // row by enrollment (user ├ù course) ΓÇö the anchor going forward.
            const cardExists = await manager.findOne(
                FlashcardCardEntity,
                {
                    where: {
                        id: cardId,
                    },
                    relations: {
                        deck: true,
                    },
                },
            )
            if (!cardExists) {
                throw new FlashcardCardNotFoundException({
                    flashcardCardId: cardId,
                })
            }

            // resolve-or-create the trial enrollment for this user ├ù course; set it on
            // the row going forward (we still set user_id during the re-key transition).
            // A deck without a course (global deck) leaves enrollment unset.
            const courseId = cardExists.deck?.courseId ?? null
            const enrollment = courseId
                ? await this.userService.resolveOrCreateTrialEnrollment(
                    userId,
                    courseId,
                )
                : null

            // read the prior review state (defaults for a brand-new card)
            const existing = await manager.findOne(
                UserFlashcardReviewEntity,
                {
                    where: {
                        // userId is a real column; flashcardCardId is a @RelationId
                        // (virtual, not queryable) ΓÇö filter through the relation
                        userId,
                        flashcardCard: {
                            id: cardId,
                        },
                    },
                },
            )
            const prevEase = existing?.ease ?? 2.5
            const prevInterval = existing?.intervalDays ?? 0
            const prevRepetitions = existing?.repetitions ?? 0

            // apply SM-2
            const next = this.applySm2({
                grade,
                prevEase,
                prevInterval,
                prevRepetitions,
            })

            const now = new Date()
            const dueAt = new Date(now.getTime() + next.intervalDays * 24 * 60 * 60 * 1000)

            // upsert the per-(user, card) review row. XP is granted ONLY on the
            // first-ever review of this card by this user ΓÇö the `!existing` branch
            // (no prior review row). Repeat reviews grant 0.
            let xpEarned = 0
            if (existing) {
                await manager.update(
                    UserFlashcardReviewEntity,
                    {
                        id: existing.id,
                    },
                    {
                        ease: next.ease,
                        intervalDays: next.intervalDays,
                        repetitions: next.repetitions,
                        dueAt,
                        lastReviewedAt: now,
                        // backfill enrollment on a pre-existing row that predates the re-key
                        ...(enrollment && !existing.enrollmentId
                            ? {
                                enrollment: {
                                    id: enrollment.id,
                                },
                            }
                            : {
                            }),
                    },
                )
            } else {
                const review = manager.create(
                    UserFlashcardReviewEntity,
                    {
                        userId,
                        flashcardCardId: cardId,
                        ease: next.ease,
                        intervalDays: next.intervalDays,
                        repetitions: next.repetitions,
                        dueAt,
                        lastReviewedAt: now,
                        ...(enrollment
                            ? {
                                enrollment,
                            }
                            : {
                            }),
                    },
                )
                await manager.save(review)

                // grant the flat first-review XP + Coin in the SAME tx. Idempotent on
                // (source, refId) ΓÇö the review-row id is the stable ref, so a retry
                // of this exact grade never double-credits. A global deck with no
                // course leaves courseId null (still a valid course-agnostic grant).
                await writeXpHistory({
                    entityManager: manager,
                    userId,
                    courseId,
                    source: XpSource.FlashcardFirstReview,
                    amount: FLASHCARD_FIRST_REVIEW_XP,
                    points: FLAT_POINTS.flashcardFirstReview,
                    refId: review.id,
                })
                xpEarned = FLASHCARD_FIRST_REVIEW_XP
            }

            // append to the immutable review-event log so history-based stats
            // (streak / retention / total / per-session) can be projected from it.
            // `sessionId` attributes the grade to the client's current review session
            // (null when the client threaded none ΓåÆ an untracked grade).
            await manager.save(
                manager.create(
                    FlashcardReviewEventEntity,
                    {
                        userId,
                        flashcardCardId: cardId,
                        grade,
                        reviewedAt: now,
                        sessionId: sessionId ?? null,
                    },
                ),
            )

            return {
                dueAt,
                xpEarned,
            }
        })
    }

    /**
     * Preview the interval (in days) each SM-2 grade would schedule from a card's
     * current state, WITHOUT persisting ΓÇö powers the rating buttons so the learner
     * sees the consequence of each choice. Same arithmetic as {@link review}.
     *
     * @param prior - the card's current ease / interval / repetitions.
     * @returns the per-grade next interval in days.
     */
    previewIntervals(
        prior: Omit<ApplySm2Params, "grade">,
    ): FlashcardNextIntervals {
        const intervalForGrade = (grade: number): number =>
            this.applySm2({
                grade,
                ...prior,
            }).intervalDays
        return {
            again: intervalForGrade(0),
            hard: intervalForGrade(1),
            good: intervalForGrade(2),
            easy: intervalForGrade(3),
        }
    }

    /**
     * Resolves, once per DISTINCT owning course, whether the viewer is entitled to
     * read premium cards from that course ΓÇö mirrors `ContentHandler.isEntitled`
     * (`content.handler.ts:283-300`). A batch of cards (due queue or an id-based
     * rehydrate) can span several courses, so this is checked per course rather
     * than once for the whole batch; `UserService.checkEnrollment` is backed by a
     * single per-user cached set, so repeat calls for the same user are cheap.
     *
     * @param cards - The loaded cards (each card's `deck.courseId` identifies its course).
     * @param userId - Active user id.
     * @returns Entitlement keyed by course id ΓÇö only courses that actually own a
     *   premium card in this batch are checked.
     */
    private async resolveEntitlementByCourseId(
        cards: Array<FlashcardCardEntity>,
        userId: string,
    ): Promise<Map<string, boolean>> {
        const entitledByCourseId = new Map<string, boolean>()
        for (const card of cards) {
            if (!card.isPremium) {
                continue
            }
            const courseId = card.deck?.courseId
            if (!courseId || entitledByCourseId.has(courseId)) {
                continue
            }
            entitledByCourseId.set(
                courseId,
                await this.userService.checkEnrollment(
                    userId,
                    courseId,
                ),
            )
        }
        return entitledByCourseId
    }

    /**
     * Whether the viewer may read THIS card's answer: true for a free card, or a
     * premium card whose owning course is entitled per
     * {@link resolveEntitlementByCourseId}. A premium card whose course could not
     * be resolved (no deck loaded) fails closed (not entitled) rather than leaking.
     *
     * @param card - The card being served.
     * @param entitledByCourseId - Per-course entitlement from {@link resolveEntitlementByCourseId}.
     */
    private isEntitledToCard(
        card: FlashcardCardEntity,
        entitledByCourseId: Map<string, boolean>,
    ): boolean {
        if (!card.isPremium) {
            return true
        }
        const courseId = card.deck?.courseId
        return Boolean(courseId && entitledByCourseId.get(courseId))
    }

    /**
     * The pure SM-2 update over the prior scheduling state.
     *
     * @param params - the grade and prior ease/interval/repetitions.
     * @returns the next ease / interval / repetitions.
     */
    private applySm2(
        {
            grade,
            prevEase,
            prevInterval,
            prevRepetitions,
        }: ApplySm2Params,
    ): ApplySm2Result {
        // Again: a lapse ΓåÆ restart the repetition count and re-show tomorrow.
        // Ease is left untouched on a lapse (classic SM-2 only adjusts ease on recall).
        if (grade === GRADE_AGAIN) {
            return {
                ease: prevEase,
                intervalDays: 1,
                repetitions: 0,
            }
        }
        // successful recall: bump repetitions and recompute ease
        const repetitions = prevRepetitions + 1
        const delta = 0.1 - (3 - grade) * (0.08 + (3 - grade) * 0.02)
        const ease = Math.max(EASE_FLOOR,
            prevEase + delta)
        // interval schedule: 1d ΓåÆ 6d ΓåÆ round(prevInterval * ease)
        const intervalDays = repetitions === 1
            ? 1
            : repetitions === 2
                ? 6
                : Math.round(prevInterval * ease)
        return {
            ease,
            intervalDays,
            repetitions,
        }
    }
}

/**
 * Params for starting (or resume-replacing) ONE resumable flashcard reviewer
 * session over a single deck.
 */
export interface StartFlashcardReviewSessionParams {
    /** The learner starting the draw. */
    userId: string
    /** The deck this session reviews ΓÇö review sessions are scoped to ONE deck. */
    deckId: string
    /** The `flashcard_cards.id` set for this deck, in the order they will be reviewed. */
    cardIds: Array<string>
    /**
     * Which cards to actually persist into the session (thß║ºy 2026-07-13 mode
     * picker ΓÇö full deck or due-only):
     * - `"full"` (default) ΓÇö keep the whole `cardIds` set (review the entire deck).
     * - `"due"` ΓÇö keep only the cards that need review (no review row yet OR past
     *   `due_at`), matching the deck's `dueCount` semantics. When the filter would
     *   yield ZERO cards the full set is kept instead (never persist an empty draw).
     */
    mode?: "full" | "due"
}

/** Result of persisting a new resumable flashcard review session. */
export interface StartFlashcardReviewSessionResult {
    /** Id of the persisted session ΓÇö pass to `syncFlashcardReviewSessionProgress` / `completeFlashcardReviewSession`. */
    sessionId: string
}

/** Params for syncing an in-flight flashcard review session's position/progress. */
export interface SyncFlashcardReviewSessionProgressParams {
    /** The learner the session belongs to (ownership check). */
    userId: string
    /** Id of the session to sync. */
    sessionId: string
    /** 0-based index of the card the learner is currently on. */
    currentIndex: number
    /** Cards actually graded so far this session (via `reviewFlashcard`). */
    reviewedCount: number
    /**
     * 0-indexed card positions graded this session (order-independent) ΓÇö
     * drives the FE per-segment green, distinct from the plain `reviewedCount`.
     * Optional: when omitted the column is left unchanged (same tolerance the
     * sync already has); when provided it overwrites the row's set.
     */
    gradedIndexes?: Array<number>
    /** Client-reported XP bookkeeping snapshot so far this session (no server grant ΓÇö see {@link CompleteFlashcardReviewSessionParams}). */
    xpEarned: number
}

/** Result of one sync attempt. */
export interface SyncFlashcardReviewSessionProgressResult {
    /** Whether the sync was applied ΓÇö false when the session is not found/owned, or is no longer "in_progress". */
    success: boolean
}

/**
 * Params for recording a finished flashcard review session.
 *
 * `reviewFlashcard` (the per-card SM-2 grading mutation) grants no XP today
 * and writes no `xp_histories` row ΓÇö so, unlike `completeFlashcardQuizSession`,
 * this does NOT compute or grant any XP. `xpEarned` here is purely the
 * client-reported bookkeeping snapshot to persist onto the row for
 * history/stats display; it is never used to write `xp_histories` and never
 * double-grants anything.
 */
export interface CompleteFlashcardReviewSessionParams {
    /** The learner who finished the session (ownership check). */
    userId: string
    /** Id of the session to complete. */
    sessionId: string
    /** Final reviewed-card count to snapshot onto the row. */
    reviewedCount: number
    /** Final XP bookkeeping snapshot to persist onto the row (NOT granted server-side ΓÇö see class doc). */
    xpEarned: number
}

/** Result of recording a finished flashcard review session. */
export interface CompleteFlashcardReviewSessionResult {
    /** The reviewed-card count snapshotted onto the row. */
    reviewedCount: number
    /** The XP bookkeeping value snapshotted onto the row (echoed back, not a server grant). */
    xpEarned: number
}

/** Params for looking up the learner's resumable in-progress review session for one deck. */
export interface FindMyInProgressFlashcardReviewSessionParams {
    /** Viewer whose in-flight session is being looked up. */
    userId: string
    /** Deck to scope the lookup to. */
    deckId: string
}

/**
 * The learner's most recent RESUMABLE flashcard review session for one deck.
 * Null when there is none (no draw was ever left in-flight, the last draw
 * already completed/was abandoned, or the last sync is older than the resume
 * window).
 */
export interface MyInProgressFlashcardReviewSessionResultData {
    /** Id of the persisted session ΓÇö pass to `syncFlashcardReviewSessionProgress` / `completeFlashcardReviewSession`. */
    sessionId: string
    /** The `flashcard_cards.id` set for this deck, in review order. */
    cardIds: Array<string>
    /** 0-based index of the card the learner was on at the last sync. */
    currentIndex: number
    /** Cards actually graded so far this session. */
    reviewedCount: number
    /** 0-indexed card positions graded this session (order-independent) ΓÇö rehydrates the FE per-segment green on resume. */
    gradedIndexes: Array<number>
    /** Client-reported XP bookkeeping snapshot so far this session. */
    xpEarned: number
    /** When this session was last synced/updated. */
    updatedAt: Date
}

/** Params for looking up a review session directly by its id (ownership-checked, no deckId needed upfront). */
export interface FindFlashcardReviewSessionByIdParams {
    /** Viewer whose session this must belong to (ownership check). */
    userId: string
    /** Id of the session to look up. */
    sessionId: string
}

/**
 * A review session found by id, with its deck identity attached ΓÇö so the FE's
 * unified `/review/sessions/[sessionId]` route can resolve full context
 * (which deck, its title) from the id ALONE, no `deckId` carried in the URL
 * (thß║ºy 2026-07-11: no `deckId` query param needed ΓÇö session already persists everything).
 */
export interface FlashcardReviewSessionByIdResultData extends MyInProgressFlashcardReviewSessionResultData {
    /** The deck this session reviews. */
    deckId: string
    /** The deck's display title (for the work-session header identity). */
    deckTitle: string
}

import {
    Injectable,
} from "@nestjs/common"
import {
    CvVerificationLevel,
    InjectPrimaryPostgreSQLEntityManager,
} from "@modules/databases"
import type {
    EntityManager,
} from "typeorm"
import type {
    CvVerificationUserIdRow,
    ResolveCvVerificationLevelForCourseParams,
    ResolveCvVerificationLevelsParams,
} from "./types"

@Injectable()
/**
 * Classifies candidates into a {@link CvVerificationLevel} ΓÇö a recruiter TRUST
 * signal tied to REAL, graded StarCi work (never to payment or CV count). A
 * strong external developer who only uploaded a CV is `SelfReported`; graded
 * challenge work is `ActivityBacked`; a passed capstone is `CapstoneVerified`.
 *
 * Used by the recruiter marketplace ({@link import("../../../features/api/core/graphql/queries/users/talent-candidates/talent-candidates.service").TalentCandidatesService})
 * to badge candidates and break depth ties (verified above self-reported).
 * Deliberately does NOT touch the CV-score contact gate
 * ({@link import("./consultant-contact-gate.service").ConsultantContactGateService})
 * ΓÇö this is an additive trust tier, not a new access lock.
 */
export class CvVerificationService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
    ) {}

    /**
     * Classifies a BATCH of users into their verification level with two batched
     * existence probes (passed-capstone, graded-challenge). Batch-shaped so the
     * marketplace can classify a whole candidate page in two queries.
     *
     * @param params - {@link ResolveCvVerificationLevelsParams}
     * @returns a map of `userId ΓåÆ level`; every requested user is present (defaults to `SelfReported`).
     *
     * @example
     * const levels = await service.resolveLevels({ userIds })
     * levels.get(userId) // CvVerificationLevel.CapstoneVerified
     */
    async resolveLevels(
        {
            userIds,
        }: ResolveCvVerificationLevelsParams,
    ): Promise<Map<string, CvVerificationLevel>> {
        // empty batch ΓåÆ nothing to classify, skip the DB round-trips
        if (userIds.length === 0) {
            return new Map()
        }

        // two existence probes over the whole batch in parallel ΓÇö each returns
        // the DISTINCT set of user ids that HAVE that class of graded StarCi work
        const [
            capstoneRows,
            challengeRows,
        ] = await Promise.all([
            this.loadUsersWithPassedCapstone(userIds),
            this.loadUsersWithGradedChallenge(userIds),
        ])

        // index both sets for O(1) membership tests during classification
        const capstoneUserIds = new Set(capstoneRows.map((row) => row.user_id))
        const challengeUserIds = new Set(challengeRows.map((row) => row.user_id))

        // classify every REQUESTED user (not just the ones with a row) so callers
        // always get a level back ΓÇö absent from both sets means self-reported
        const levels = new Map<string, CvVerificationLevel>()
        userIds.forEach((userId) => {
            // a passed capstone/milestone task is the strongest proof of real project work
            if (capstoneUserIds.has(userId)) {
                levels.set(userId,
                    CvVerificationLevel.CapstoneVerified)
                return
            }
            // else any AI-graded challenge submission still proves hands-on StarCi work
            if (challengeUserIds.has(userId)) {
                levels.set(userId,
                    CvVerificationLevel.ActivityBacked)
                return
            }
            // no graded StarCi work at all ΓåÆ the CV stands on self-reported claims only
            levels.set(userId,
                CvVerificationLevel.SelfReported)
        })
        return levels
    }

    /**
     * Convenience single-user classification (thin wrapper over
     * {@link resolveLevels}).
     *
     * @param userId - the user to classify.
     * @returns the user's verification level (defaults to `SelfReported`).
     */
    async resolveLevel(userId: string): Promise<CvVerificationLevel> {
        // reuse the batch path with a one-element batch so the SQL stays single-sourced
        const levels = await this.resolveLevels({
            userIds: [userId] 
        })
        // missing key can only happen for an empty input, which never reaches here
        return levels.get(userId) ?? CvVerificationLevel.SelfReported
    }

    /**
     * Deterministic "CV trust score" for a level ΓÇö REPLACES the old AI-judged
     * `cv_generations.score` rubric everywhere that number gated something
     * (recruiter contact, job-readiness). No AI, no CV prose involved: a pure
     * function of the existence-checked signal, so it is count-independent and
     * payment-independent by construction ΓÇö a learner with 1 enrollment who
     * passed a capstone scores identically to one with 5 enrollments who also
     * passed one, and nothing here can be inflated by writing more into a CV
     * (there is no CV text in this computation at all).
     *
     * CAPSTONE-ONLY SCORE (2026-07-05, teacher-approved). Only a passed
     * CAPSTONE (`CapstoneVerified`) produces a positive gating score. A merely
     * `ActivityBacked` learner (graded challenges but no capstone) scores 0
     * like `SelfReported`: challenges are practice exercises that never go on
     * the CV, so they must not silently unlock a recruiter's contact details
     * either ΓÇö "a recruiter trusts a real capstone project, not a pile of
     * graded exercises". The 3-level classification is still kept for the
     * marketplace tie-break ({@link rankOf}); it just no longer feeds the gate.
     *
     * CAUTION: the step value (100) and the downstream unlock threshold
     * ({@link import("./constants").CV_SCORE_UNLOCK_THRESHOLD}) are a
     * placeholder pending calibration ΓÇö deliberately NOT tuned yet (2026-07-05:
     * thß║ºy: defer real score checks; gate on CV score first so everyone is treated fairly).
     * Fairness of the FORMULA is what's locked here; the THRESHOLD is not.
     *
     * @param level - the verification level to score.
     * @returns 100 (passed capstone) / 0 (activity-backed or self-reported).
     */
    scoreOf(level: CvVerificationLevel): number {
        switch (level) {
        case CvVerificationLevel.CapstoneVerified:
            return 100
        // challenges (activity-backed) do NOT count toward the CV/gate score ΓÇö
        // only a real passed capstone does; treated the same as self-reported
        case CvVerificationLevel.ActivityBacked:
        case CvVerificationLevel.SelfReported:
            return 0
        }
    }

    /**
     * Sort rank of a level ΓÇö higher = stronger StarCi proof. Lets the marketplace
     * break equal-depth ties by surfacing verified candidates above self-reported
     * ones without importing the enum's ordering into another module.
     *
     * @param level - the verification level to rank.
     * @returns 2 (capstone) / 1 (activity) / 0 (self-reported).
     */
    rankOf(level: CvVerificationLevel): number {
        // explicit switch keeps the ordering exhaustive + obvious at the call site
        switch (level) {
        case CvVerificationLevel.CapstoneVerified:
            return 2
        case CvVerificationLevel.ActivityBacked:
            return 1
        case CvVerificationLevel.SelfReported:
            return 0
        }
    }

    /**
     * Same classification as {@link resolveLevel}, but scoped to ONE course ΓÇö
     * "did this learner pass a capstone / get a challenge graded IN THIS
     * course's enrollment", not anywhere on the platform. Powers the
     * per-track CV pillar ({@link import("../../../features/api/core/graphql/queries/users/job-readiness/job-readiness.service").JobReadinessService}),
     * which is per-course by design ΓÇö reusing the platform-wide
     * {@link resolveLevel} there would let 1 unrelated capstone in ANOTHER
     * course inflate THIS track's depth, which is exactly the count/cross-track
     * leak the fair-monetization axiom forbids. Existence-checked (not summed)
     * within the course, so it stays count-independent the same way
     * {@link resolveLevel} is platform-wide.
     *
     * @param params - the learner + the course to scope the check to.
     * @returns the level, defaulting to `SelfReported` when neither signal is present.
     */
    async resolveLevelForCourse(
        {
            userId,
            courseId,
        }: ResolveCvVerificationLevelForCourseParams,
    ): Promise<CvVerificationLevel> {
        const [
            capstoneRow,
            challengeRow,
        ] = await Promise.all([
            this.entityManager.query<Array<CvVerificationUserIdRow>>(
                `
                SELECT DISTINCT e.user_id AS user_id
                FROM enrollments e
                JOIN user_milestone_tasks umt ON umt.enrollment_id = e.id
                JOIN user_milestone_task_attempts umta ON umta.user_milestone_task_id = umt.id
                WHERE e.user_id = $1 AND e.course_id = $2 AND umta.passed = true
                LIMIT 1
                `,
                [
                    userId,
                    courseId,
                ],
            ),
            this.entityManager.query<Array<CvVerificationUserIdRow>>(
                `
                SELECT DISTINCT ucs.user_id AS user_id
                FROM user_challenge_submissions ucs
                JOIN user_challenge_submission_attempts ucsa ON ucsa.user_challenge_submission_id = ucs.id
                JOIN enrollments e ON e.id = ucs.enrollment_id
                WHERE ucs.user_id = $1 AND e.course_id = $2 AND ucsa.score IS NOT NULL
                LIMIT 1
                `,
                [
                    userId,
                    courseId,
                ],
            ),
        ])

        if (capstoneRow.length > 0) {
            return CvVerificationLevel.CapstoneVerified
        }
        if (challengeRow.length > 0) {
            return CvVerificationLevel.ActivityBacked
        }
        return CvVerificationLevel.SelfReported
    }

    /**
     * Distinct users with ΓëÑ1 PASSED capstone/milestone task attempt, reached via
     * their enrollments. A passed capstone is the strongest verification signal.
     *
     * @param userIds - the candidate batch's user ids.
     * @returns one row per qualifying user id.
     */
    private async loadUsersWithPassedCapstone(userIds: Array<string>): Promise<Array<CvVerificationUserIdRow>> {
        // join enrollments ΓåÆ user_milestone_tasks ΓåÆ attempts, keep only passed
        // attempts, and collapse to one distinct user_id per qualifying user
        return this.entityManager.query<Array<CvVerificationUserIdRow>>(
            `
            SELECT DISTINCT e.user_id AS user_id
            FROM enrollments e
            JOIN user_milestone_tasks umt ON umt.enrollment_id = e.id
            JOIN user_milestone_task_attempts umta ON umta.user_milestone_task_id = umt.id
            WHERE e.user_id = ANY($1) AND umta.passed = true
            `,
            [
                userIds,
            ],
        )
    }

    /**
     * Distinct users with ΓëÑ1 AI-graded challenge submission attempt. A non-null
     * `score` means the attempt was actually processed/graded (regardless of
     * pass/fail) ΓÇö proof the user did + submitted real hands-on StarCi work,
     * unlike a bare uploaded CV. (Challenge attempts carry no `passed` boolean,
     * so "graded" is the cleanest available signal.)
     *
     * @param userIds - the candidate batch's user ids.
     * @returns one row per qualifying user id.
     */
    private async loadUsersWithGradedChallenge(userIds: Array<string>): Promise<Array<CvVerificationUserIdRow>> {
        // join submissions ΓåÆ attempts, keep only scored (graded) attempts, and
        // collapse to one distinct user_id per qualifying user
        return this.entityManager.query<Array<CvVerificationUserIdRow>>(
            `
            SELECT DISTINCT ucs.user_id AS user_id
            FROM user_challenge_submissions ucs
            JOIN user_challenge_submission_attempts ucsa ON ucsa.user_challenge_submission_id = ucs.id
            WHERE ucs.user_id = ANY($1) AND ucsa.score IS NOT NULL
            `,
            [
                userIds,
            ],
        )
    }
}

